68	@RestController
69	@CrossOrigin(exposedHeaders = "errors, content-type")
70	@RequestMapping("/api")
71	public class OwnerRestControllerV1 implements OwnersApi {
72	
73	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
74	
75	    private final ClinicService clinicService;
76	
77	    private final OwnerMapper ownerMapper;
78	
79	    private final PetMapper petMapper;
80	
81	    private final VisitMapper visitMapper;
82	
83	    private final TelephoneNormalizer telephoneNormalizer;
84	
85	    private final AddressNormalizer addressNormalizer;
86	
87	    private final EmailNormalizer emailNormalizer;
88	
89	    public OwnerRestControllerV1(ClinicService clinicService,
90	                                 OwnerMapper ownerMapper,
91	                                 PetMapper petMapper,
92	                                 VisitMapper visitMapper,
93	                                 TelephoneNormalizer telephoneNormalizer,
94	                                 AddressNormalizer addressNormalizer,
95	                                 EmailNormalizer emailNormalizer) {
96	        this.clinicService = clinicService;
97	        this.ownerMapper = ownerMapper;
98	        this.petMapper = petMapper;
99	        this.visitMapper = visitMapper;
100	        this.telephoneNormalizer = telephoneNormalizer;
101	        this.addressNormalizer = addressNormalizer;
102	        this.emailNormalizer = emailNormalizer;
103	    }
104	
105	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
106	    @Override
107	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
108	        Collection<Owner> owners;
109	        if (lastName != null) {
110	            owners = this.clinicService.findOwnerByLastName(lastName);
111	        } else {
112	            owners = this.clinicService.findAllOwners();
113	        }
114	        if (owners.isEmpty()) {
115	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
116	        }
117	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
118	    }
119	
120	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
121	    @Override
122	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
123	        return withOwner(ownerId, owner ->
124	            new ResponseEntity<>(toOwnerDtoWithDerivedFields(owner), HttpStatus.OK));
125	    }
126	
127	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
128	    @Override
129	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
130	        ownerFieldsDto.setAddress(addressNormalizer.normalize(ownerFieldsDto.getAddress()));
131	        rejectBlankOwnerFields(ownerFieldsDto);
132	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
133	        rejectInvalidPostcode(ownerFieldsDto.getCity(), ownerFieldsDto.getPostcode());
134	        rejectCityAtCapacity(ownerFieldsDto.getCity());
135	        rejectFutureRegistrationDate(ownerFieldsDto.getRegistrationDate());
136	        LocalDate registrationDate = businessDay(effectiveRegistrationDate(ownerFieldsDto.getRegistrationDate()));
137	        rejectDailyRegistrationLimit(registrationDate);
138	        String normalizedTelephone = telephoneNormalizer.normalize(ownerFieldsDto.getTelephone());
139	        ownerFieldsDto.setTelephone(normalizedTelephone);
140	        String normalizedEmail = emailNormalizer.normalize(ownerFieldsDto.getEmail());
141	        ownerFieldsDto.setEmail(normalizedEmail);
142	        HttpHeaders headers = new HttpHeaders();
143	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
144	        owner.setRegistrationDate(registrationDate);
145	        owner.setCustomerCode(customerCode(owner));
146	        owner.setNamesakeCount(namesakeCount(owner.getFirstName(), owner.getLastName()));
147	        if (sharesHousehold) {
148	            owner.setHouseholdId(householdId(owner.getLastName(), owner.getAddress()));
149	        }
150	        rejectDuplicateIdentity(owner);
151	        this.clinicService.saveOwner(owner);
152	        AUDIT.info("Owner created: id={} customerCode={} registrationDate={} membershipLevel={}",
153	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
154	            ownerMapper.membershipLevel(owner));
155	        OwnerDto ownerDto = toOwnerDtoWithDerivedFields(owner);
156	        headers.setLocation(UriComponentsBuilder.newInstance()
157	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
158	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
159	    }
160	
161	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
162	    @Override
163	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
164	        return withOwner(ownerId, currentOwner -> {
165	            currentOwner.setAddress(ownerFieldsDto.getAddress());
166	            currentOwner.setCity(ownerFieldsDto.getCity());
167	            currentOwner.setFirstName(ownerFieldsDto.getFirstName());
168	            currentOwner.setLastName(ownerFieldsDto.getLastName());
169	            currentOwner.setTelephone(ownerFieldsDto.getTelephone());
170	            currentOwner.setEmail(emailNormalizer.normalize(ownerFieldsDto.getEmail()));
171	            this.clinicService.saveOwner(currentOwner);
172	            return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
173	        });
174	    }
175	
176	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
177	    @Transactional
178	    @Override
179	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
180	        return withOwner(ownerId, owner -> {
181	            this.clinicService.deleteOwner(owner);
182	            return new ResponseEntity<>(HttpStatus.NO_CONTENT);
183	        });
184	    }
185	
186	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
187	    @Override
188	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
189	        return withOwner(ownerId, owner -> {
190	            HttpHeaders headers = new HttpHeaders();
191	            Pet pet = petMapper.toPet(petFieldsDto);
192	            owner.setId(ownerId);
193	            pet.setOwner(owner);
194	            pet.getType().setName(null);
195	            this.clinicService.savePet(pet);
196	            PetDto petDto = petMapper.toPetDto(pet);
197	            headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
198	                .buildAndExpand(pet.getId()).toUri());
199	            return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
200	        });
201	    }
202	
203	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
204	    @Override
205	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
206	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
207	        if (currentOwner != null) {
208	            Pet currentPet = this.clinicService.findPetById(petId);
209	            if (currentPet != null) {
210	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
211	                currentPet.setName(petFieldsDto.getName());
212	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
213	                this.clinicService.savePet(currentPet);
214	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
215	            }
216	        }
217	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
218	    }
219	
220	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
221	    @Override
222	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
223	        HttpHeaders headers = new HttpHeaders();
224	        Visit visit = visitMapper.toVisit(visitFieldsDto);
225	        Pet pet = new Pet();
226	        pet.setId(petId);
227	        visit.setPet(pet);
228	        this.clinicService.saveVisit(visit);
229	        VisitDto visitDto = visitMapper.toVisitDto(visit);
230	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
231	            .buildAndExpand(visit.getId()).toUri());
232	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
233	    }
234	
235	
236	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
237	    @Override
238	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
239	        Owner owner = this.clinicService.findOwnerById(ownerId);
240	        if (owner != null) {
241	            Pet pet = owner.getPet(petId);
242	            if (pet != null) {
243	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
244	            }
245	        }
246	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
247	    }
248	
249	    /**
250	     * Loads the owner with the given id and, when it exists, produces the response through
251	     * {@code action}; when no such owner exists a {@code 404 Not Found} is returned instead. The
252	     * single-owner endpoints share this "find the owner or report 404" preamble, so the lookup and
253	     * the not-found response are written in exactly one place rather than copied into each method.
254	     *
255	     * @param ownerId the id of the owner to load
256	     * @param action builds the response for an existing owner
257	     * @param <T> the response body type
258	     * @return the result of {@code action} for an existing owner, otherwise a 404 response
259	     */
260	    private <T> ResponseEntity<T> withOwner(Integer ownerId, Function<Owner, ResponseEntity<T>> action) {
261	        Owner owner = this.clinicService.findOwnerById(ownerId);
262	        if (owner == null) {
263	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
264	        }
265	        return action.apply(owner);
266	    }
267	
268	    /**
269	     * Maps a persisted owner to its {@link OwnerDto} and populates the read-only fields that are
270	     * derived from server-side state rather than stored columns (the {@code bulkSignupWarning} flag
271	     * and the {@code identityKey}). Both the create endpoint and the single-owner read endpoint
272	     * return their owner through this method, so an owner is decorated identically on either path
273	     * and each derived field is computed in exactly one place.
274	     *
275	     * @param owner the persisted owner to represent
276	     * @return the owner DTO with its derived read-only fields populated
277	     */
278	    private OwnerDto toOwnerDtoWithDerivedFields(Owner owner) {
279	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
280	        ownerDto.setBulkSignupWarning(bulkSignupWarning(owner.getRegistrationDate()));
281	        ownerDto.setIdentityKey(identityKey(owner));
282	        return ownerDto;
283	    }
284	
285	    /**
286	     * Rejects an owner whose required text fields are blank (whitespace-only). Missing (null)
287	     * and empty fields are already rejected by Bean Validation on {@link OwnerFieldsDto}; this
288	     * closes the gap for {@code address} and {@code city}, whose values may be non-empty yet
289	     * blank (e.g. {@code "   "}). The offending field names are reported through an
290	     * {@link InvalidOwnerFieldsException}, which the {@code ExceptionControllerAdvice} renders
291	     * as a 400 response carrying an {@code errors} array of field names.
292	     *
293	     * @param ownerFieldsDto the submitted owner fields
294	     * @throws InvalidOwnerFieldsException if one or more required fields are blank
295	     */
296	    private void rejectBlankOwnerFields(OwnerFieldsDto ownerFieldsDto) {
297	        List<String> blankFields = new ArrayList<>();
298	        addIfBlank(blankFields, "firstName", ownerFieldsDto.getFirstName());
299	        addIfBlank(blankFields, "lastName", ownerFieldsDto.getLastName());
300	        addIfBlank(blankFields, "address", ownerFieldsDto.getAddress());
301	        addIfBlank(blankFields, "city", ownerFieldsDto.getCity());
302	        addIfBlank(blankFields, "telephone", ownerFieldsDto.getTelephone());
303	        if (!blankFields.isEmpty()) {
304	            throw new InvalidOwnerFieldsException(blankFields);
305	        }
306	    }
307	
308	    private void addIfBlank(List<String> blankFields, String field, String value) {
309	        if (value != null && value.isBlank()) {
310	            blankFields.add(field);
311	        }
312	    }
313	
314	    /**
315	     * Validates the owner's optional {@code postcode} against its {@code city} region. Postcode is
316	     * validated only when present, so an owner created without one is accepted unchanged. A supplied
317	     * postcode is already constrained to four digits by Bean Validation on {@link OwnerFieldsDto}; this
318	     * additionally rejects a well-formed postcode that is out of range for the city's region using the
319	     * shared {@link Region#acceptsPostcode(int) region-to-postcode} table ({@code NSW 2000-2099},
320	     * {@code VIC 3000-3099}, {@code QLD 4000-4099}). A city with no known region accepts any 4-digit
321	     * postcode. An out-of-range postcode is reported through an {@link InvalidOwnerPostcodeException},
322	     * which the {@code ExceptionControllerAdvice} renders as a 400 response.
323	     *
324	     * @param city the city of the owner being created
325	     * @param postcode the supplied postcode, or {@code null} when omitted
326	     * @throws InvalidOwnerPostcodeException if the postcode is out of range for the city's region
327	     */
328	    private void rejectInvalidPostcode(String city, String postcode) {
329	        if (postcode == null || postcode.isBlank()) {
330	            return;
331	        }
332	        Region.forCity(city).ifPresent(region -> {
333	            if (!region.acceptsPostcode(Integer.parseInt(postcode))) {
334	                throw new InvalidOwnerPostcodeException(postcode, city);
335	            }
336	        });
337	    }
338	
339	    /**
340	     * Number of leading hex characters of the identity hash retained as the {@code HASH8} segment of
341	     * the {@code customerCode}.
342	     */
343	    private static final int CUSTOMER_CODE_HASH_LENGTH = 8;
344	
345	    /**
346	     * Builds the {@code customerCode} assigned to a newly created owner, formatted
347	     * {@code '<REGION>-<HASH8>'}: {@code REGION} is the owner's canonical region code resolved from
348	     * its {@code postcode} (falling back to its {@code city}) through the shared
349	     * {@link Region#code(String, String)}, and {@code HASH8} is the first 8 upper-case hex characters
350	     * of the SHA-256 digest of the owner's normalized telephone followed by its last name
351	     * (e.g. {@code 'NSW-1A2B3C4D'}). The code carries no sequence number, so it is a deterministic
352	     * function of the owner's region and telephone-plus-name identity.
353	     *
354	     * @param owner the owner being created, with its telephone already normalized
355	     * @return the formatted customer code
356	     */
357	    private String customerCode(Owner owner) {
358	        String region = Region.code(owner.getPostcode(), owner.getCity());
359	        String hash8 = hashPrefix(owner.getTelephone() + owner.getLastName(), CUSTOMER_CODE_HASH_LENGTH);
360	        return region + "-" + hash8;
361	    }
362	
363	    /**
364	     * Counts how many existing owners already share the given {@code firstName} and {@code lastName},
365	     * compared case-insensitively (using {@link java.util.Locale#ROOT}-independent
366	     * {@link String#equalsIgnoreCase(String)}). The count reflects the owners present before the
367	     * current create, so a name that is unique on create yields {@code 0}. The value is stored on the
368	     * new owner and surfaced as the read-only {@code namesakeCount} field.
369	     *
370	     * @param firstName the first name of the owner being created
371	     * @param lastName the last name of the owner being created
372	     * @return the number of existing owners with the same first and last name (case-insensitive)
373	     */
374	    private int namesakeCount(String firstName, String lastName) {
375	        return (int) this.clinicService.findAllOwners().stream()
376	            .filter(owner -> equalsIgnoreCase(owner.getFirstName(), firstName)
377	                && equalsIgnoreCase(owner.getLastName(), lastName))
378	            .count();
379	    }
380	
381	    private boolean equalsIgnoreCase(String a, String b) {
382	        return a == null ? b == null : a.equalsIgnoreCase(b);
383	    }
384	
385	    /**
386	     * The maximum number of owners a single city may contain. Once a city already holds this many
387	     * owners, further owners in that city are rejected by {@link #rejectCityAtCapacity(String)}.
388	     */
389	    private static final long MAX_OWNERS_PER_CITY = 50L;
390	
391	    /**
392	     * Rejects a create request whose city already contains {@link #MAX_OWNERS_PER_CITY} or more
393	     * owners. Existing owners are matched to the requested city case-insensitively (using
394	     * {@link java.util.Locale#ROOT}-independent {@link String#equalsIgnoreCase(String)}), mirroring
395	     * the per-city counting used for the customer code. A city at capacity is reported through an
396	     * {@link OwnerCityAtCapacityException}, which the {@code ExceptionControllerAdvice} renders as a
397	     * 409 Conflict response.
398	     *
399	     * @param city the city of the owner being created
400	     * @throws OwnerCityAtCapacityException if the city already holds the maximum number of owners
401	     */
402	    private void rejectCityAtCapacity(String city) {
403	        if (ownersInCity(city) >= MAX_OWNERS_PER_CITY) {
404	            throw new OwnerCityAtCapacityException(city);
405	        }
406	    }
407	
408	    /**
409	     * Counts the existing owners whose {@code city} matches the given city, compared
410	     * case-insensitively (see {@link #equalsIgnoreCase(String, String)}). Used by the per-city
411	     * capacity check ({@link #rejectCityAtCapacity(String)}) to count a city's owners.
412	     *
413	     * @param city the city to count owners for
414	     * @return the number of existing owners in that city
415	     */
416	    private long ownersInCity(String city) {
417	        return this.clinicService.findAllOwners().stream()
418	            .filter(owner -> equalsIgnoreCase(owner.getCity(), city))
419	            .count();
420	    }
421	
422	    /**
423	     * The maximum number of owners that may be registered on a single day. Once this many owners
424	     * already carry a given {@code registrationDate}, further owners for that date are rejected by
425	     * {@link #rejectDailyRegistrationLimit(LocalDate)}.
426	     */
427	    private static final long MAX_OWNERS_PER_DAY = 100L;
428	
429	    /**
430	     * Resolves the effective registration date for a create request: the value supplied in the
431	     * request when present, otherwise the server's current date. The result is the raw effective
432	     * date before the business-day adjustment applied by {@link #businessDay(LocalDate)}.
433	     *
434	     * @param suppliedDate the registration date from the request, or {@code null} when omitted
435	     * @return the supplied date, or today when none was supplied
436	     */
437	    private LocalDate effectiveRegistrationDate(LocalDate suppliedDate) {
438	        return suppliedDate != null ? suppliedDate : LocalDate.now();
439	    }
440	
441	    /**
442	     * Rejects a create request whose supplied {@code registrationDate} lies after the server's
443	     * current date. A registration date may be supplied to backdate a create - and is defaulted to
444	     * today when omitted - but it may never be in the future. The check is applied to the raw
445	     * supplied value before the business-day adjustment ({@link #businessDay(LocalDate)}), so a
446	     * future date is rejected regardless of how that adjustment would move it. A future date is
447	     * reported through a {@link FutureRegistrationDateException}, which the
448	     * {@code ExceptionControllerAdvice} renders as a 400 Bad Request response naming the
449	     * {@code registrationDate} field.
450	     *
451	     * @param suppliedDate the registration date from the request, or {@code null} when omitted
452	     * @throws FutureRegistrationDateException if the supplied date is later than the server date
453	     */
454	    private void rejectFutureRegistrationDate(LocalDate suppliedDate) {
455	        if (suppliedDate != null && suppliedDate.isAfter(LocalDate.now())) {
456	            throw new FutureRegistrationDateException(suppliedDate);
457	        }
458	    }
459	
460	    /**
461	     * Adjusts a date so it falls on a business day. A Saturday is rolled forward to the following
462	     * Monday and a Sunday to the next day (Monday); any weekday is returned unchanged. Applied to
463	     * the effective registration date so that a weekend value - whether supplied in the request or
464	     * defaulted to the server date - is stored as the next Monday, and every value derived from the
465	     * registration date (such as the membership number's year segment and the daily create-limit
466	     * bucket) uses the adjusted business day.
467	     *
468	     * @param date the effective registration date
469	     * @return the same date when it is a weekday, otherwise the next Monday
470	     */
471	    private LocalDate businessDay(LocalDate date) {
472	        DayOfWeek dayOfWeek = date.getDayOfWeek();
473	        if (dayOfWeek == DayOfWeek.SATURDAY) {
474	            return date.plusDays(2);
475	        }
476	        if (dayOfWeek == DayOfWeek.SUNDAY) {
477	            return date.plusDays(1);
478	        }
479	        return date;
480	    }
481	
482	    /**
483	     * Rejects a create request once {@link #MAX_OWNERS_PER_DAY} or more owners have already been
484	     * created on the given day, counted by {@code registrationDate}. A day at capacity is reported
485	     * through a {@link DailyOwnerRegistrationLimitException}, which the {@code ExceptionControllerAdvice}
486	     * renders as a 429 Too Many Requests response.
487	     *
488	     * @param date the registration date of the owner being created (today)
489	     * @throws DailyOwnerRegistrationLimitException if the day already holds the maximum number of owners
490	     */
491	    private void rejectDailyRegistrationLimit(LocalDate date) {
492	        if (ownersRegisteredOn(date) >= MAX_OWNERS_PER_DAY) {
493	            throw new DailyOwnerRegistrationLimitException(date);
494	        }
495	    }
496	
497	    /**
498	     * Counts the existing owners whose {@code registrationDate} equals the given day. Shared by the
499	     * hard daily create limit ({@link #rejectDailyRegistrationLimit(LocalDate)}) and the soft
500	     * {@code bulkSignupWarning} flag ({@link #bulkSignupWarning(LocalDate)}) so both accumulate a
501	     * day's owners identically.
502	     *
503	     * @param date the registration date to count owners for
504	     * @return the number of existing owners registered on that day
505	     */
506	    private long ownersRegisteredOn(LocalDate date) {
507	        return this.clinicService.findAllOwners().stream()
508	            .filter(owner -> date.equals(owner.getRegistrationDate()))
509	            .count();
510	    }
511	
512	    /**
513	     * The soft daily create threshold above which the read-only {@code bulkSignupWarning} flag is
514	     * raised. Once more than this many owners share a {@code registrationDate}, that day is flagged
515	     * as unusually high volume - a warning well below the hard {@link #MAX_OWNERS_PER_DAY} cap.
516	     */
517	    private static final long BULK_SIGNUP_WARNING_THRESHOLD = 80L;
518	
519	    /**
520	     * Derives the read-only {@code bulkSignupWarning} flag for an owner: {@code true} when more than
521	     * {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners have been created (counted by
522	     * {@code registrationDate}) on the given day, otherwise {@code false}. Uses the same per-day
523	     * accumulation as {@link #rejectDailyRegistrationLimit(LocalDate)}. A {@code null} date (an owner
524	     * without a registration date, such as seed data) is never flagged.
525	     *
526	     * @param date the owner's registration date (the day it was created), or {@code null}
527	     * @return {@code true} if the day already holds more than the warning threshold of owners
528	     */
529	    private boolean bulkSignupWarning(LocalDate date) {
530	        if (date == null) {
531	            return false;
532	        }
533	        return ownersRegisteredOn(date) > BULK_SIGNUP_WARNING_THRESHOLD;
534	    }
535	
536	    /**
537	     * Rejects a create request whose derived {@code identityKey} exactly equals an existing owner's.
538	     * The identity key consolidates the former separate telephone, email and household duplicate
539	     * checks into a single value: {@code normalizedTelephone + '|' + (email or empty) + '|' +
540	     * (householdId or empty)} (see {@link #identityKey(Owner)}). Because the telephone is part of the
541	     * key, two members of the same household (same {@code householdId}) with different telephones have
542	     * different identity keys and are both allowed; only an exact full-key match is a duplicate. A
543	     * collision is reported through a {@link DuplicateOwnerIdentityException}, which the
544	     * {@code ExceptionControllerAdvice} renders as a 409 Conflict response.
545	     *
546	     * @param owner the fully-populated owner being created (telephone, email and household id set)
547	     * @throws DuplicateOwnerIdentityException if an existing owner has the same identity key
548	     */
549	    private void rejectDuplicateIdentity(Owner owner) {
550	        String key = identityKey(owner);
551	        boolean duplicate = existingOwnerMatches(this::identityKey, key);
552	        if (duplicate) {
553	            throw new DuplicateOwnerIdentityException(key);
554	        }
555	    }
556	
557	    /**
558	     * Reduces an owner to its derived {@code identityKey}, formatted
559	     * {@code '<normalizedTelephone>|<email>|<householdId>'}: the owner's telephone reduced to its
560	     * canonical E.164 form (see {@link TelephoneNormalizer#canonicalize(String)}), the owner's
561	     * normalized (lower-cased) email or the empty string when absent (see
562	     * {@link EmailNormalizer#normalize(String)}), and the owner's {@code householdId} or the empty
563	     * string when absent, joined by {@code '|'}. Two owners are duplicates exactly when their whole
564	     * identity keys are equal. The key never contains {@code null} segments, so the create endpoint's
565	     * single duplicate check compares this one value across owners.
566	     *
567	     * @param owner the owner to derive the identity key for
568	     * @return the owner's identity key
569	     */
570	    private String identityKey(Owner owner) {
571	        String telephone = telephoneNormalizer.canonicalize(owner.getTelephone());
572	        String normalizedEmail = emailNormalizer.normalize(owner.getEmail());
573	        String email = normalizedEmail == null ? "" : normalizedEmail;
574	        String household = owner.getHouseholdId() == null ? "" : owner.getHouseholdId();
575	        return telephone + "|" + email + "|" + household;
576	    }
577	
578	    /**
579	     * Reports whether any existing owner already carries the given comparison {@code key}, derived
580	     * from each owner by {@code keyExtractor}. Owners for which the extractor yields {@code null}
581	     * are ignored. The create endpoint's duplicate checks use this to reduce both an existing owner
582	     * and the owner being created to the same canonical key and reject a match.
583	     *
584	     * @param keyExtractor derives an owner's canonical comparison key (may return {@code null})
585	     * @param key the canonical key of the owner being created
586	     * @return {@code true} if some existing owner shares the key
587	     */
588	    private boolean existingOwnerMatches(Function<Owner, String> keyExtractor, String key) {
589	        return this.clinicService.findAllOwners().stream()
590	            .map(keyExtractor)
591	            .filter(Objects::nonNull)
592	            .anyMatch(key::equals);
593	    }
594	
595	    /**
596	     * Delimiter joining the canonical household fields when deriving the shared {@code householdId}.
597	     * A run of whitespace is collapsed to a single space by {@link #canonicalizeHousehold(String)}, so
598	     * this newline can never occur inside a canonical value and the two fields cannot bleed into one
599	     * another across the join.
600	     */
601	    private static final String HOUSEHOLD_KEY_DELIMITER = "\n";
602	
603	    /**
604	     * Reduces a household field ({@code lastName} or {@code address}) to a canonical form for
605	     * case-insensitive, whitespace-insensitive comparison: leading and trailing whitespace is
606	     * trimmed, every run of internal whitespace is collapsed to a single space, and the result is
607	     * lower-cased using {@link java.util.Locale#ROOT} so comparison is locale-independent.
608	     *
609	     * @param value the raw field value, or {@code null}
610	     * @return the canonical value, or {@code null} when {@code value} is {@code null}
611	     */
612	    private String canonicalizeHousehold(String value) {
613	        return value == null ? null : value.trim().replaceAll("\\s+", " ").toLowerCase(java.util.Locale.ROOT);
614	    }
615	
616	    /**
617	     * Derives the stable, shared {@code householdId} for an owner joining a household via
618	     * {@code sharesHousehold}. The identifier is a deterministic function of the canonical
619	     * {@code lastName} and {@code address} (see {@link #canonicalizeHousehold(String)}), so every
620	     * owner with the same last name at the same address - regardless of casing or spacing - is
621	     * assigned the identical value. It is the first 16 upper-case hex characters of the SHA-256 hash
622	     * of the two canonical fields joined by a delimiter that cannot occur in the input.
623	     *
624	     * @param lastName the last name of the owner being created
625	     * @param address the address of the owner being created
626	     * @return the shared household identifier
627	     */
628	    private String householdId(String lastName, String address) {
629	        String key = canonicalizeHousehold(lastName) + HOUSEHOLD_KEY_DELIMITER + canonicalizeHousehold(address);
630	        return hashPrefix(key, HOUSEHOLD_ID_LENGTH);
631	    }
632	
633	    /**
634	     * Number of leading hex characters of the household hash retained as the shared
635	     * {@code householdId}.
636	     */
637	    private static final int HOUSEHOLD_ID_LENGTH = 16;
638	
639	    /**
640	     * Computes the leading {@code length} upper-case hex characters of the SHA-256 digest of the
641	     * UTF-8 bytes of {@code input}. This is the shared hashing primitive behind the derived
642	     * identifiers that fingerprint owner fields - such as the household-scoped {@code householdId} -
643	     * so every such identifier is produced by the same algorithm and differs only in the value it
644	     * hashes and the number of hex characters it keeps.
645	     *
646	     * @param input the value to hash
647	     * @param length the number of leading hex characters to keep
648	     * @return the leading {@code length} upper-case hex characters of the SHA-256 digest
649	     */
650	    private String hashPrefix(String input, int length) {
651	        try {
652	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
653	                .digest(input.getBytes(java.nio.charset.StandardCharsets.UTF_8));
654	            StringBuilder sb = new StringBuilder(digest.length * 2);
655	            for (byte b : digest) {
656	                sb.append(String.format("%02X", b));
657	            }
658	            return sb.substring(0, length);
659	        } catch (java.security.NoSuchAlgorithmException e) {
660	            throw new IllegalStateException("SHA-256 is required but unavailable", e);
661	        }
662	    }
663	}
